<?php
namespace App\Jobs;
use App\Domain\BulkImport\Enums\{MigrationBatchStatus,MigrationItemStatus};use App\Domain\BulkImport\Services\MigrationItemValidator;use App\Models\MigrationBatch;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;
class ValidateMigrationBatch implements ShouldQueue{use Queueable;public int $timeout=1200;public function __construct(public int $batchId){$this->onQueue('imports');}public function handle(MigrationItemValidator $validator):void{$batch=MigrationBatch::findOrFail($this->batchId);$batch->update(['status'=>MigrationBatchStatus::Validating]);$batch->items()->whereIn('status',[MigrationItemStatus::Pending,MigrationItemStatus::Invalid,MigrationItemStatus::Warning,MigrationItemStatus::Valid])->orderBy('id')->chunkById(500,function($items)use($validator){foreach($items as $item)$validator->validate($item);});$valid=$batch->items()->where('status',MigrationItemStatus::Valid)->count();$warnings=$batch->items()->where('status',MigrationItemStatus::Warning)->count();$failed=$batch->items()->where('status',MigrationItemStatus::Invalid)->count();$status=$failed?MigrationBatchStatus::FailedValidation:($warnings?MigrationBatchStatus::ValidatedWithWarnings:MigrationBatchStatus::Validated);$batch->update(['valid_items'=>$valid,'warning_items'=>$warnings,'failed_items'=>$failed,'status'=>$status]);}}
